template:
% 参数由系统自动注入；正三棱台 ABC-A'B'C'，斜二测立体视角
% AB为下底前边，C在右后方；上下底位似相似，OO'为竖直的高
% 可见棱实线，被遮挡棱虚线；视觉归一化：最长外接尺寸约6单位
% ==========================================================
% 下底面顶点坐标：AB沿x轴，C在斜二测深度方向
% ==========================================================
\pgfmathsetmacro{\Ax}{0}
\pgfmathsetmacro{\Ay}{0}
\pgfmathsetmacro{\Bx}{\base}
\pgfmathsetmacro{\By}{0}
% C点：AB中点向右深度偏移，模拟斜二测立体效果
\pgfmathsetmacro{\Cx}{0.5 * \base + 0.35 * \depth}
\pgfmathsetmacro{\Cy}{0.25 * \depth}
% ==========================================================
% 下底面重心O
% ==========================================================
\pgfmathsetmacro{\Ox}{(\Ax + \Bx + \Cx)/3}
\pgfmathsetmacro{\Oy}{(\Ay + \By + \Cy)/3}
% ==========================================================
% 上底面：位似变换，相似比k=top/base，中心O'在O正上方
% ==========================================================
\pgfmathsetmacro{\k}{\top / \base}
\pgfmathsetmacro{\Opx}{\Ox}
\pgfmathsetmacro{\Opy}{\Oy + \height}
% 上底顶点：P' = O' + k*(P - O) 位似公式
\pgfmathsetmacro{\Apx}{\Opx + \k*(\Ax - \Ox)}
\pgfmathsetmacro{\Apy}{\Opy + \k*(\Ay - \Oy)}
\pgfmathsetmacro{\Bpx}{\Opx + \k*(\Bx - \Ox)}
\pgfmathsetmacro{\Bpy}{\Opy + \k*(\By - \Oy)}
\pgfmathsetmacro{\Cpx}{\Opx + \k*(\Cx - \Ox)}
\pgfmathsetmacro{\Cpy}{\Opy + \k*(\Cy - \Oy)}
% ==========================================================
% 视觉归一化
% ==========================================================
\pgfmathsetmacro{\xmin}{min(\Ax,\Bx,\Cx,\Apx,\Bpx,\Cpx,\Ox,\Opx)}
\pgfmathsetmacro{\xmax}{max(\Ax,\Bx,\Cx,\Apx,\Bpx,\Cpx,\Ox,\Opx)}
\pgfmathsetmacro{\ymin}{min(\Ay,\By,\Cy,\Apy,\Bpy,\Cpy,\Oy,\Opy)}
\pgfmathsetmacro{\ymax}{max(\Ay,\By,\Cy,\Apy,\Bpy,\Cpy,\Oy,\Opy)}
\pgfmathsetmacro{\figscale}{6 / max(\xmax-\xmin, \ymax-\ymin)}
% ==========================================================
% 绘图开始
% ==========================================================
\begin{tikzpicture}[
    scale=\figscale,
    every node/.style={
        font=\small,
        fill=none,
        inner sep=1.5pt
    }
]
    % 定义全部坐标点
    \coordinate (A)   at (\Ax,\Ay);
    \coordinate (B)   at (\Bx,\By);
    \coordinate (C)   at (\Cx,\Cy);
    \coordinate (Ap)  at (\Apx,\Apy);
    \coordinate (Bp)  at (\Bpx,\Bpy);
    \coordinate (Cp)  at (\Cpx,\Cpy);
    \coordinate (O)   at (\Ox,\Oy);
    \coordinate (Op)  at (\Opx,\Opy);

    % ========== 下底面ABC ==========
    \draw[thick] (A)--(B);  % AB前底边，实线
    \ifnum\showhidden>0
        \draw[dashed,thick] (A)--(C);  % AC被遮挡，虚线
        \draw[dashed,thick] (B)--(C);  % BC被遮挡，虚线
    \else
        \draw[thick] (A)--(C);
        \draw[thick] (B)--(C);
    \fi

    % ========== 三条侧棱 ==========
    \draw[thick] (A)--(Ap);  % AA'左前棱，实线可见
    \draw[thick] (B)--(Bp);  % BB'右前棱，实线可见
    \ifnum\showhidden>0
        \draw[dashed,thick] (C)--(Cp);  % CC'后棱，被遮挡虚线
    \else
        \draw[thick] (C)--(Cp);
    \fi

    % ========== 上底面A'B'C'（全部可见，实线） ==========
    \draw[thick] (Ap)--(Bp);
    \draw[thick] (Ap)--(Cp);
    \draw[thick] (Bp)--(Cp);

    % ========== 辅助线：重心连线OO' ==========
    \ifnum\showaux>0
        \draw[dashed,thick] (O)--(Op);  % OO'棱台的高，虚线
    \fi

    % ========== 顶点标签 ==========
    \ifnum\showverts>0
        \node[below left=2pt] at (A) {$A$};
        \node[below right=2pt] at (B) {$B$};
        \node[right=2pt] at (C) {$C$};
        \node[above left=2pt] at (Ap) {$A'$};
        \node[above right=2pt] at (Bp) {$B'$};
        \node[above=2pt] at (Cp) {$C'$};
    \fi

    % ========== 辅助点标记 ==========
    \ifnum\showpoints>0
        \fill (O) circle [radius=0.8pt];
        \fill (Op) circle [radius=0.8pt];
        \node[left=2pt] at (O) {$O$};
        \node[left=2pt] at (Op) {$O'$};
    \fi
\end{tikzpicture}
